"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["37230"],{18038(e){e.exports=JSON.parse('{"id":"F304","slug":"effective-duration-convexity","name":"Effective Duration and Convexity","subject":"Fixed Income","section":"Bonds","topic":"Callable and putable bonds","level":"Intermediate","aliases":["option adjusted duration","duration of callable bonds","empirical duration","full repricing"],"formula":{"latex":"D_{eff}=\\\\frac{P_{-}-P_{+}}{2P_{0}\\\\Delta y},\\\\quad C_{eff}=\\\\frac{P_{-}+P_{+}-2P_{0}}{P_{0}(\\\\Delta y)^{2}}","also":[],"text":"Effective duration = (Price when yields fall - Price when yields rise) / (2 x Price now x Yield change); Effective convexity = (P- + P+ - 2 x P0) / (P0 x Yield change^2)"},"symbols":[{"symbol":"P_0","meaning":"Price now","unit":"money"},{"symbol":"P_-","meaning":"Price after yields fall by the amount Delta y","unit":"money"},{"symbol":"P_+","meaning":"Price after yields rise by the amount Delta y","unit":"money"},{"symbol":"Delta y","meaning":"Size of the yield shift, as a decimal","unit":"per year"}],"when_to_use":"Use it for bonds whose cash flows change when rates change, such as callable, putable and mortgage bonds. Ordinary duration formulas assume fixed cash flows, so you reprice the bond with a model after shifting yields down and up and use the results.","worked_example":{"problem":"A callable bond is priced at 102.0. If yields fall 0.5 percentage points its price becomes 104.5, and if they rise 0.5 percentage points it becomes 99.7. What are the effective duration and convexity?","inputs":{"p0":102,"pm":104.5,"pp":99.7,"dy":0.5},"steps":[{"label":"Effective duration = (P- - P+) / (2 x P0 x dy)","working":"(104.5-99.7) / (2 x 102 x 0.005)","value":"4.706"},{"label":"Effective convexity = (P- + P+ - 2 x P0) / (P0 x dy^2)","working":"(104.5+99.7-2 x 102) / (102 x 0.005^2)","value":"78.4"}],"answer":"The effective duration is 4.706, so the price moves about 4.706% for each 1 percentage point change in yield. The effective convexity is 78.4. A callable bond often shows lower or even negative convexity when yields fall, because the price is capped near the call price."},"calculator":{"available":true,"inputs":[{"id":"p0","label":"Price now","unit":"money","type":"number","default":102,"hint":""},{"id":"pm","label":"Price if yields fall","unit":"money","type":"number","default":104.5,"hint":""},{"id":"pp","label":"Price if yields rise","unit":"money","type":"number","default":99.7,"hint":""},{"id":"dy","label":"Size of the yield shift","unit":"%","type":"number","default":0.5,"hint":""}],"checks":[{"expr":"dy>0 and p0>0","message":"The shift and the price must be above zero."}],"steps":[{"id":"de","label":"Effective duration = (P- - P+) / (2 x P0 x dy)","expr":"(pm-pp)/(2*p0*dy)","format":"num3"},{"id":"ce","label":"Effective convexity = (P- + P+ - 2 x P0) / (P0 x dy^2)","expr":"(pm+pp-2*p0)/(p0*dy^2)","format":"num1"}],"results":["de","ce"],"percent_inputs_typed_as_whole_numbers":true,"tested_against":{"de":4.705882352941177,"ce":78.43137254901514}},"finder":{"finds":"Rate sensitivity for bonds with embedded options","needs":"Prices after yields shift down and up"},"related":[{"slug":"duration","name":"Macaulay and Modified Duration"},{"slug":"convexity","name":"Bond Convexity"},{"slug":"callable-bond-value","name":"Callable and Putable Bond Value"}],"related_ids":["F288","F289","F303"],"group":"Markets and instruments","mathml":"<span class=\\"katex\\"><math xmlns=\\"http://www.w3.org/1998/Math/MathML\\" display=\\"block\\"><semantics><mrow><msub><mi>D</mi><mrow><mi>e</mi><mi>f</mi><mi>f</mi></mrow></msub><mo>=</mo><mfrac><mrow><msub><mi>P</mi><mo lspace=\\"0em\\" rspace=\\"0em\\">\u2212</mo></msub><mo>\u2212</mo><msub><mi>P</mi><mo lspace=\\"0em\\" rspace=\\"0em\\">+</mo></msub></mrow><mrow><mn>2</mn><msub><mi>P</mi><mn>0</mn></msub><mi mathvariant=\\"normal\\">\u0394</mi><mi>y</mi></mrow></mfrac><mo separator=\\"true\\">,</mo><mspace width=\\"1em\\"/><msub><mi>C</mi><mrow><mi>e</mi><mi>f</mi><mi>f</mi></mrow></msub><mo>=</mo><mfrac><mrow><msub><mi>P</mi><mo lspace=\\"0em\\" rspace=\\"0em\\">\u2212</mo></msub><mo>+</mo><msub><mi>P</mi><mo lspace=\\"0em\\" rspace=\\"0em\\">+</mo></msub><mo>\u2212</mo><mn>2</mn><msub><mi>P</mi><mn>0</mn></msub></mrow><mrow><msub><mi>P</mi><mn>0</mn></msub><mo stretchy=\\"false\\">(</mo><mi mathvariant=\\"normal\\">\u0394</mi><mi>y</mi><msup><mo stretchy=\\"false\\">)</mo><mn>2</mn></msup></mrow></mfrac></mrow><annotation encoding=\\"application/x-tex\\">D_{eff}=\\\\frac{P_{-}-P_{+}}{2P_{0}\\\\Delta y},\\\\quad C_{eff}=\\\\frac{P_{-}+P_{+}-2P_{0}}{P_{0}(\\\\Delta y)^{2}}</annotation></semantics></math></span>","alsoMathml":[],"prev":{"slug":"ear","name":"Effective Annual Rate (EAR)"},"next":{"slug":"effective-spread","name":"Effective Spread and Price Impact"},"lesson":null,"total":522}')}}]);